import re
import sys

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LINK_RE = re.compile(r"\[[^\]]*\]\(([^)]+)\)")


def is_relative(target: str) -> bool:
    return not (
        target.startswith(("http://", "https://", "mailto:", "#", "sandbox:"))
        or target == ""
    )


def main() -> int:
